head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p > M > $]<br/>현재 Scope 안에서 jQuery Selector 를 인자로 받아 jQuery 객체를 반환합니다.",
    "validation" : [
        "selector(필수) 파라미터로 jQuery Selector 문자열을 설정할 수 있어야 합니다. (컴포넌트 조회 시 렌더링 ID 를 설정)",
        "jQuery 객체를 반환해야 합니다. (jQuery 가 로드되어 있지 않으면 반환값이 없음)",
        ".wq() 를 사용하여 웹스퀘어 객체로 변환 가능해야 합니다. (예: .wq('invoke', 'setDisabled', 'true'))"
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_execute_onclick = function () {
    var scenario = par_scenario.getValue();

    if (scenario === "1") {
        // 시나리오 1: 기본 반환 타입 확인
        var $obj = $p.$("#mf_group1");
        var isJquery = ($obj instanceof jQuery);
        wf_body_bottom.getObj("scwin").setReturnValue("$p.$('#mf_group1') 호출");
        wf_body_bottom.getObj("scwin").setReturnValue("반환 타입 : " + typeof $obj + " / jQuery 여부 : " + isJquery + " / length : " + $obj.length);
    } else if (scenario === "2") {
        // 시나리오 2: .wq('invoke', 'setDisabled', 'true') - API 가이드 예시
        $p.$("#mf_group1").wq("invoke", "setDisabled", "true");
        var disabledAfter = ibx_target1.getDisabled();
        wf_body_bottom.getObj("scwin").setReturnValue("$p.$('#mf_group1').wq('invoke', 'setDisabled', 'true') 호출");
        wf_body_bottom.getObj("scwin").setReturnValue("setDisabled('true') 호출 후 ibx_target1.getDisabled() = " + disabledAfter);
    } else if (scenario === "3") {
        // 시나리오 3: 존재하지 않는 selector → 빈 jQuery 객체
        var $obj = $p.$("#mf_not_exist");
        wf_body_bottom.getObj("scwin").setReturnValue("$p.$('#mf_not_exist') 호출 (존재하지 않는 selector)");
        wf_body_bottom.getObj("scwin").setReturnValue("존재하지 않는 selector → length : " + $obj.length);
    }
}
